const express=require('express');const {Pool}=require('pg');const http=require('http');const {spawn}=require('child_process');
const app=express();app.use(express.json({limit:'2mb'}));app.use(express.urlencoded({extended:true}));
const port=Number(process.env.PORT||8080);const innerPort=port+1;const pool=new Pool({connectionString:process.env.DATABASE_URL,ssl:false});
const schema=`CREATE TABLE IF NOT EXISTS suppliers(id SERIAL PRIMARY KEY,name_ar VARCHAR(200) NOT NULL,phone VARCHAR(50),address TEXT,active BOOLEAN DEFAULT TRUE,created_at TIMESTAMPTZ DEFAULT now());CREATE TABLE IF NOT EXISTS products(id SERIAL PRIMARY KEY,sku VARCHAR(50) UNIQUE,name_ar VARCHAR(200) NOT NULL,unit VARCHAR(30) DEFAULT 'unit',purchase_price NUMERIC(14,2) DEFAULT 0,sale_price NUMERIC(14,2) DEFAULT 0,stock_min NUMERIC(14,2) DEFAULT 0,inventory_account VARCHAR(20) DEFAULT '1301',sale_account VARCHAR(20) DEFAULT '4103',active BOOLEAN DEFAULT TRUE,created_at TIMESTAMPTZ DEFAULT now());CREATE TABLE IF NOT EXISTS batches(id SERIAL PRIMARY KEY,product_id INT NOT NULL REFERENCES products(id),batch_no VARCHAR(100) NOT NULL,expiry_date DATE,qty NUMERIC(14,2) NOT NULL DEFAULT 0,cost NUMERIC(14,2) NOT NULL DEFAULT 0,created_at TIMESTAMPTZ DEFAULT now(),UNIQUE(product_id,batch_no));CREATE TABLE IF NOT EXISTS stock_movements(id SERIAL PRIMARY KEY,product_id INT NOT NULL REFERENCES products(id),batch_id INT REFERENCES batches(id),movement_date DATE DEFAULT CURRENT_DATE,type VARCHAR(30) NOT NULL,qty NUMERIC(14,2) NOT NULL,cost NUMERIC(14,2) DEFAULT 0,reference VARCHAR(100),description TEXT,created_at TIMESTAMPTZ DEFAULT now());CREATE TABLE IF NOT EXISTS purchases(id SERIAL PRIMARY KEY,purchase_no VARCHAR(40) UNIQUE NOT NULL,supplier_id INT REFERENCES suppliers(id),purchase_date DATE DEFAULT CURRENT_DATE,total NUMERIC(14,2) NOT NULL DEFAULT 0,paid NUMERIC(14,2) NOT NULL DEFAULT 0,status VARCHAR(20) DEFAULT 'unpaid');CREATE TABLE IF NOT EXISTS purchase_lines(id SERIAL PRIMARY KEY,purchase_id INT REFERENCES purchases(id) ON DELETE CASCADE,product_id INT REFERENCES products(id),batch_no VARCHAR(100),expiry_date DATE,qty NUMERIC(14,2) NOT NULL,cost NUMERIC(14,2) NOT NULL,total NUMERIC(14,2) NOT NULL);CREATE TABLE IF NOT EXISTS supplier_payments(id SERIAL PRIMARY KEY,supplier_id INT REFERENCES suppliers(id),payment_date DATE DEFAULT CURRENT_DATE,amount NUMERIC(14,2) NOT NULL,reference VARCHAR(100),description TEXT);CREATE TABLE IF NOT EXISTS pharmacy_sales(id SERIAL PRIMARY KEY,sale_no VARCHAR(40) UNIQUE NOT NULL,patient_id INT,prescription_no VARCHAR(100),sale_date DATE DEFAULT CURRENT_DATE,total NUMERIC(14,2) NOT NULL DEFAULT 0,paid NUMERIC(14,2) NOT NULL DEFAULT 0,status VARCHAR(20) DEFAULT 'unpaid');CREATE TABLE IF NOT EXISTS pharmacy_sale_lines(id SERIAL PRIMARY KEY,sale_id INT REFERENCES pharmacy_sales(id) ON DELETE CASCADE,product_id INT REFERENCES products(id),batch_id INT REFERENCES batches(id),qty NUMERIC(14,2) NOT NULL,price NUMERIC(14,2) NOT NULL,total NUMERIC(14,2) NOT NULL);CREATE TABLE IF NOT EXISTS cost_centers(id SERIAL PRIMARY KEY,code VARCHAR(30) UNIQUE NOT NULL,name_ar VARCHAR(150) NOT NULL,active BOOLEAN DEFAULT TRUE);CREATE INDEX IF NOT EXISTS idx_batches_product ON batches(product_id);CREATE INDEX IF NOT EXISTS idx_stock_product ON stock_movements(product_id);CREATE INDEX IF NOT EXISTS idx_purchases_date ON purchases(purchase_date);`;
function num(v){const x=Number(v);if(!Number.isFinite(x)||x<0)throw Error('القيمة غير صحيحة');return Math.round(x*100)/100}function today(){return new Date()}
async function init(){await pool.query(schema);await pool.query(`INSERT INTO cost_centers(code,name_ar) VALUES('MAIN','المركز الرئيسي') ON CONFLICT(code) DO NOTHING`)}
async function journal(lines,date,desc,ref){const d=lines.reduce((s,x)=>s+num(x.debit||0),0),c=lines.reduce((s,x)=>s+num(x.credit||0),0);if(Math.abs(d-c)>.001)throw Error('القيد غير متوازن');for(const x of lines){const q=await pool.query('SELECT 1 FROM accounts WHERE code=$1 AND active=true',[x.account_code]);if(!q.rowCount)throw Error('الحساب غير موجود: '+x.account_code)}const e=await pool.query('INSERT INTO journal_entries(entry_date,description,reference) VALUES($1,$2,$3) RETURNING id',[date||today(),desc,ref||null]);for(const x of lines)await pool.query('INSERT INTO journal_lines(entry_id,account_code,debit,credit) VALUES($1,$2,$3,$4)',[e.rows[0].id,x.account_code,num(x.debit||0),num(x.credit||0)]);return e.rows[0].id}
function forward(req,res){const body=req.body&&Object.keys(req.body).length?JSON.stringify(req.body):null;const headers={...req.headers,host:'127.0.0.1:'+innerPort};if(body)headers['content-length']=Buffer.byteLength(body);const r=http.request({hostname:'127.0.0.1',port:innerPort,path:req.originalUrl,method:req.method,headers},x=>{res.status(x.statusCode);for(const[k,v]of Object.entries(x.headers))if(k!=='transfer-encoding')res.setHeader(k,v);x.pipe(res)});r.on('error',e=>res.status(502).json({error:'backend unavailable',details:e.message}));if(body)r.write(body);r.end()}
app.get('/api/advanced/health',async(req,res)=>{try{await pool.query('SELECT 1');res.json({ok:true,database:true,modules:['suppliers','inventory','purchases','pharmacy_sales','supplier_payments','cost_centers']})}catch(e){res.status(503).json({ok:false,error:e.message})}});
app.get('/api/suppliers',async(req,res)=>{try{res.json((await pool.query('SELECT * FROM suppliers ORDER BY id DESC')).rows)}catch(e){res.status(500).json({error:e.message})}});
app.post('/api/suppliers',async(req,res)=>{try{if(!req.body.name_ar)throw Error('اسم المورد مطلوب');const r=await pool.query('INSERT INTO suppliers(name_ar,phone,address) VALUES($1,$2,$3) RETURNING *',[req.body.name_ar,req.body.phone||null,req.body.address||null]);res.json(r.rows[0])}catch(e){res.status(400).json({error:e.message})}});
app.get('/api/products',async(req,res)=>{try{const r=await pool.query(`SELECT p.*,COALESCE(SUM(b.qty),0) stock FROM products p LEFT JOIN batches b ON b.product_id=p.id GROUP BY p.id ORDER BY p.id DESC`);res.json(r.rows)}catch(e){res.status(500).json({error:e.message})}});
app.post('/api/products',async(req,res)=>{try{if(!req.body.name_ar)throw Error('اسم الصنف مطلوب');const r=await pool.query('INSERT INTO products(sku,name_ar,unit,purchase_price,sale_price,stock_min) VALUES($1,$2,$3,$4,$5,$6) RETURNING *',[req.body.sku||null,req.body.name_ar,req.body.unit||'unit',num(req.body.purchase_price||0),num(req.body.sale_price||0),num(req.body.stock_min||0)]);res.json(r.rows[0])}catch(e){res.status(400).json({error:e.message})}});
app.get('/api/inventory',async(req,res)=>{try{const r=await pool.query(`SELECT p.id,p.sku,p.name_ar,p.unit,p.purchase_price,p.sale_price,p.stock_min,COALESCE(SUM(b.qty),0) stock,COUNT(b.id) batches FROM products p LEFT JOIN batches b ON b.product_id=p.id GROUP BY p.id ORDER BY p.name_ar`);res.json(r.rows)}catch(e){res.status(500).json({error:e.message})}});
app.get('/api/inventory/:productId/batches',async(req,res)=>{try{res.json((await pool.query(`SELECT b.*,p.name_ar product_name FROM batches b JOIN products p ON p.id=b.product_id WHERE b.product_id=$1 ORDER BY b.expiry_date NULLS LAST,b.id`,[req.params.productId])).rows)}catch(e){res.status(500).json({error:e.message})}});
app.get('/api/stock-movements',async(req,res)=>{try{res.json((await pool.query(`SELECT m.*,p.name_ar product_name,b.batch_no FROM stock_movements m JOIN products p ON p.id=m.product_id LEFT JOIN batches b ON b.id=m.batch_id ORDER BY m.id DESC LIMIT 500`)).rows)}catch(e){res.status(500).json({error:e.message})}});
app.post('/api/purchases',async(req,res)=>{const c=await pool.connect();try{await c.query('BEGIN');const lines=req.body.lines||[];if(!lines.length)throw Error('أضف صنفاً واحداً على الأقل');let total=0;for(const x of lines){x.qty=num(x.qty);x.cost=num(x.cost);if(!x.product_id||x.qty<=0)throw Error('بيانات صنف الشراء غير صحيحة');x.total=num(x.qty*x.cost);total+=x.total}total=num(total);const paid=num(req.body.paid||0);if(paid>total)throw Error('المدفوع أكبر من الإجمالي');const r=await c.query(`INSERT INTO purchases(purchase_no,supplier_id,purchase_date,total,paid,status) VALUES('TEMP',$1,$2,$3,$4,$5) RETURNING id`,[req.body.supplier_id||null,req.body.purchase_date||today(),total,paid,paid===total?'paid':paid?'partial':'unpaid']);const id=r.rows[0].id,no='PUR-'+new Date().getFullYear()+'-'+String(id).padStart(6,'0');await c.query('UPDATE purchases SET purchase_no=$1 WHERE id=$2',[no,id]);for(const x of lines){await c.query('INSERT INTO purchase_lines(purchase_id,product_id,batch_no,expiry_date,qty,cost,total) VALUES($1,$2,$3,$4,$5,$6,$7)',[id,x.product_id,x.batch_no||('B-'+id),x.expiry_date||null,x.qty,x.cost,x.total]);const b=await c.query(`INSERT INTO batches(product_id,batch_no,expiry_date,qty,cost) VALUES($1,$2,$3,$4,$5) ON CONFLICT(product_id,batch_no) DO UPDATE SET qty=batches.qty+EXCLUDED.qty,cost=EXCLUDED.cost RETURNING id`,[x.product_id,x.batch_no||('B-'+id),x.expiry_date||null,x.qty,x.cost]);await c.query('INSERT INTO stock_movements(product_id,batch_id,type,qty,cost,reference,description) VALUES($1,$2,$3,$4,$5,$6,$7)',[x.product_id,b.rows[0].id,'purchase',x.qty,x.cost,no,'شراء مخزني']);}const due=num(total-paid);const jl=[{account_code:'1301',debit:total}];if(paid)jl.push({account_code:'1101',credit:paid});if(due)jl.push({account_code:'2101',credit:due});await journal(jl,req.body.purchase_date||today(),'فاتورة شراء '+no,no);await c.query('COMMIT');res.json({ok:true,id,purchase_no:no,total,paid,status:paid===total?'paid':paid?'partial':'unpaid'})}catch(e){await c.query('ROLLBACK');res.status(400).json({error:e.message})}finally{c.release()}});
app.post('/api/supplier-payments',async(req,res)=>{try{const amount=num(req.body.amount);if(!amount)throw Error('مبلغ السداد مطلوب');const ref=req.body.reference||'SP-'+Date.now();await journal([{account_code:'2101',debit:amount},{account_code:'1101',credit:amount}],req.body.payment_date||today(),'سداد مورد '+ref,ref);const r=await pool.query('INSERT INTO supplier_payments(supplier_id,payment_date,amount,reference,description) VALUES($1,$2,$3,$4,$5) RETURNING *',[req.body.supplier_id||null,req.body.payment_date||today(),amount,ref,req.body.description||'سداد مورد']);res.json(r.rows[0])}catch(e){res.status(400).json({error:e.message})}});
app.get('/api/supplier-payments',async(req,res)=>{try{res.json((await pool.query(`SELECT sp.*,s.name_ar supplier_name FROM supplier_payments sp LEFT JOIN suppliers s ON s.id=sp.supplier_id ORDER BY sp.id DESC`)).rows)}catch(e){res.status(500).json({error:e.message})}});
app.post('/api/pharmacy-sales',async(req,res)=>{const c=await pool.connect();try{await c.query('BEGIN');const lines=req.body.lines||[];if(!lines.length)throw Error('أضف صنفاً واحداً على الأقل');let total=0;for(const x of lines){x.qty=num(x.qty);x.price=num(x.price);if(!x.product_id||x.qty<=0)throw Error('بيانات البيع غير صحيحة');const b=await c.query(`SELECT * FROM batches WHERE id=$1 AND product_id=$2 FOR UPDATE`,[x.batch_id,x.product_id]);if(!b.rowCount||Number(b.rows[0].qty)<x.qty)throw Error('الكمية غير متوفرة في التشغيلة');x.total=num(x.qty*x.price);x.cost=num(Number(b.rows[0].cost)*x.qty);x.batch=b.rows[0];total+=x.total}total=num(total);const paid=num(req.body.paid||0);if(paid>total)throw Error('المدفوع أكبر من الإجمالي');const r=await c.query(`INSERT INTO pharmacy_sales(sale_no,patient_id,prescription_no,sale_date,total,paid,status) VALUES('TEMP',$1,$2,$3,$4,$5,$6) RETURNING id`,[req.body.patient_id||null,req.body.prescription_no||null,req.body.sale_date||today(),total,paid,paid===total?'paid':paid?'partial':'unpaid']);const id=r.rows[0].id,no='PHR-'+new Date().getFullYear()+'-'+String(id).padStart(6,'0');await c.query('UPDATE pharmacy_sales SET sale_no=$1 WHERE id=$2',[no,id]);let costTotal=0;for(const x of lines){await c.query('INSERT INTO pharmacy_sale_lines(sale_id,product_id,batch_id,qty,price,total) VALUES($1,$2,$3,$4,$5,$6)',[id,x.product_id,x.batch_id,x.qty,x.price,x.total]);await c.query('UPDATE batches SET qty=qty-$1 WHERE id=$2',[x.qty,x.batch_id]);await c.query('INSERT INTO stock_movements(product_id,batch_id,type,qty,cost,reference,description) VALUES($1,$2,$3,$4,$5,$6,$7)',[x.product_id,x.batch_id,'sale',-x.qty,x.batch.cost,no,'بيع صيدلية']);costTotal+=x.cost}const due=num(total-paid);const jl=[];if(paid)jl.push({account_code:'1101',debit:paid});if(due)jl.push({account_code:'1201',debit:due});jl.push({account_code:'4103',credit:total});if(costTotal)jl.push({account_code:'5104',debit:costTotal},{account_code:'1301',credit:costTotal});await journal(jl,req.body.sale_date||today(),'بيع صيدلية '+no,no);await c.query('COMMIT');res.json({ok:true,id,sale_no:no,total,paid,status:paid===total?'paid':paid?'partial':'unpaid'})}catch(e){await c.query('ROLLBACK');res.status(400).json({error:e.message})}finally{c.release()}});
app.get('/api/pharmacy-sales',async(req,res)=>{try{res.json((await pool.query(`SELECT s.*,COUNT(l.id)::int line_count FROM pharmacy_sales s LEFT JOIN pharmacy_sale_lines l ON l.sale_id=s.id GROUP BY s.id ORDER BY s.id DESC`)).rows)}catch(e){res.status(500).json({error:e.message})}});
app.get('/api/cost-centers',async(req,res)=>{try{res.json((await pool.query('SELECT * FROM cost_centers ORDER BY code')).rows)}catch(e){res.status(500).json({error:e.message})}});
app.post('/api/cost-centers',async(req,res)=>{try{const r=await pool.query('INSERT INTO cost_centers(code,name_ar) VALUES($1,$2) RETURNING *',[req.body.code,req.body.name_ar]);res.json(r.rows[0])}catch(e){res.status(400).json({error:e.message})}});
app.get('/api/reports/inventory-summary',async(req,res)=>{try{const r=await pool.query(`SELECT p.id,p.sku,p.name_ar,p.unit,COALESCE(SUM(b.qty),0) qty,COALESCE(SUM(b.qty*b.cost),0) stock_value,MIN(b.expiry_date) nearest_expiry FROM products p LEFT JOIN batches b ON b.product_id=p.id GROUP BY p.id ORDER BY p.name_ar`);res.json({items:r.rows,total_value:r.rows.reduce((s,x)=>s+Number(x.stock_value),0)})}catch(e){res.status(500).json({error:e.message})}});
app.use((req,res)=>forward(req,res));
const child=spawn(process.execPath,['server.js'],{env:{...process.env,PORT:String(innerPort)},stdio:['ignore','inherit','inherit']});child.on('exit',code=>{if(code&&code!==0)process.exit(code)});
init().then(()=>app.listen(port,()=>console.log('Wisdom Accounting gateway '+port+' with purchasing/inventory layer'))).catch(e=>{console.error(e);process.exit(1)});
process.on('SIGTERM',()=>{child.kill('SIGTERM');pool.end().finally(()=>process.exit(0))});